const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Smith Island, Maryland (Chesapeake Bay)
  const smithIsland = ee.Geometry.Point([-76.015, 37.983]);
  const bufferRegion = smithIsland.buffer(5000); // 5km buffer around the island

  // Time periods
  const start1999 = '1999-06-01';
  const end1999 = '1999-09-30';
  const start2019 = '2019-06-01';
  const end2019 = '2019-09-30';

  // 2. Data Acquisition - Landsat 5 for 1999, Landsat 8 for 2019
  function getLandsatCollection(startDate, endDate, collectionId) {
    return ee.ImageCollection(collectionId)
      .filterBounds(bufferRegion)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUD_COVER', 20));
  }

  const landsat5_1999 = getLandsatCollection(start1999, end1999, 'LANDSAT/LT05/C02/T1_L2');
  const landsat8_2019 = getLandsatCollection(start2019, end2019, 'LANDSAT/LC08/C02/T1_L2');

  // Check collection sizes
  const size1999 = landsat5_1999.size().getInfo();
  const size2019 = landsat8_2019.size().getInfo();

  console.log(`1999 Images: ${size1999}, 2019 Images: ${size2019}`);

  if (size1999 === 0 || size2019 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get median composites
  const composite1999 = landsat5_1999.median();
  const composite2019 = landsat8_2019.median();

  // Function to calculate land area using NDWI
  function calculateLandArea(image, year) {
    // Calculate NDWI for water detection
    let ndwi;
    if (year === 1999) {
      // Landsat 5: Green = B2, NIR = B4
      ndwi = image.normalizedDifference(['SR_B2', 'SR_B4']).rename('NDWI');
    } else {
      // Landsat 8: Green = B3, NIR = B5  
      ndwi = image.normalizedDifference(['SR_B3', 'SR_B5']).rename('NDWI');
    }

    // Classify: NDWI > 0 = water, NDWI <= 0 = land
    const landMask = ndwi.lte(0);

    // Calculate land area in square meters
    const area = landMask.multiply(ee.Image.pixelArea());

    const stats = area.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: bufferRegion,
      scale: 30,
      maxPixels: 1e9
    });

    return stats.get('NDWI');
  }

  // Calculate land areas
  const landArea1999 = calculateLandArea(composite1999, 1999);
  const landArea2019 = calculateLandArea(composite2019, 2019);

  // Get results
  const area1999 = landArea1999.getInfo();
  const area2019 = landArea2019.getInfo();

  console.log(`1999 Land Area: ${area1999 ? (area1999 / 1000000).toFixed(2) : 'N/A'} km²`);
  console.log(`2019 Land Area: ${area2019 ? (area2019 / 1000000).toFixed(2) : 'N/A'} km²`);

  // Validation
  if (area1999 === null || area2019 === null || 
      isNaN(area1999) || isNaN(area2019) ||
      area1999 <= 0 || area2019 <= 0) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare areas - if 2019 area is less than 1999, land decreased
  const percentChange = ((area2019 - area1999) / area1999 * 100);
  console.log(`Change: ${percentChange.toFixed(1)}%`);

  // Consider decrease if area reduced by more than 1% (to account for minor variations)
  if (area2019 < area1999 * 0.99) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
